schema:
CREATE TABLE nodes (node_id TEXT NOT NULL PRIMARY KEY, category TEXT DEFAULT NULL);
CREATE TABLE links (link_id TEXT NOT NULL PRIMARY KEY, link_kind TEXT DEFAULT NULL);
CREATE TABLE edges (src_id TEXT NOT NULL, dst_id TEXT NOT NULL, link_id TEXT DEFAULT NULL, PRIMARY KEY (src_id, dst_id), FOREIGN KEY (src_id) REFERENCES nodes (node_id), FOREIGN KEY (dst_id) REFERENCES nodes (node_id), FOREIGN KEY (link_id) REFERENCES links (link_id));
